// EvalConfig Configuration for inline evaluation of query results.
// Add to RetrievalAgentRequest, QueryRequest, or other evaluation-capable request schemas.
type EvalConfig struct {
	// Evaluators List of evaluators to run
	Evaluators []EvaluatorName `json:"evaluators,omitempty,omitzero"`

	// GroundTruth Ground truth data for evaluation
	GroundTruth GroundTruth `json:"ground_truth,omitempty,omitzero"`

	// Judge A unified configuration for a generative AI provider.
	//
	//
	// Example: {"max_tokens":2048,"model":"gpt-4.1","provider":"openai","temperature":0.7}
	Judge GeneratorConfig `json:"judge,omitempty,omitzero"`

	// Options Options for evaluation behavior
	Options EvalOptions `json:"options,omitempty,omitzero"`
}

// EvalOptions Options for evaluation behavior
type EvalOptions struct {
	// K K value for @K metrics (precision@k, recall@k, ndcg@k)
	K int `json:"k,omitempty,omitzero"`

	// PassThreshold Score threshold for pass/fail determination
	PassThreshold float32 `json:"pass_threshold,omitempty,omitzero"`

	// TimeoutSeconds Timeout for evaluation in seconds
	TimeoutSeconds int `json:"timeout_seconds,omitempty,omitzero"`
}

// EvalRequest Standalone evaluation request for POST /eval endpoint.
// Useful for testing evaluators without running a query.
type EvalRequest struct {
	// Context Retrieved documents/context
	Context []map[string]interface{} `json:"context,omitempty,omitzero"`

	// Evaluators List of evaluators to run
	Evaluators []EvaluatorName `json:"evaluators"`

	// GroundTruth Ground truth data for evaluation
	GroundTruth GroundTruth `json:"ground_truth,omitempty,omitzero"`

	// Judge A unified configuration for a generative AI provider.
	//
	//
	// Example: {"max_tokens":2048,"model":"gpt-4.1","provider":"openai","temperature":0.7}
	Judge GeneratorConfig `json:"judge,omitempty,omitzero"`

	// Options Options for evaluation behavior
	Options EvalOptions `json:"options,omitempty,omitzero"`

	// Output Generated output to evaluate (optional for retrieval-only)
	Output string `json:"output,omitempty,omitzero"`

	// Query Original query/input to evaluate
	Query string `json:"query,omitempty,omitzero"`

	// RetrievedIds IDs of retrieved documents (for retrieval metrics)
	RetrievedIds []string `json:"retrieved_ids,omitempty,omitzero"`
}

// EvalResult Complete evaluation result
type EvalResult struct {
	// DurationMs Total evaluation duration in milliseconds
	DurationMs int `json:"duration_ms,omitempty,omitzero"`

	// Scores Scores organized by category
	Scores EvalScores `json:"scores,omitempty,omitzero"`

	// Summary Aggregate statistics across all evaluators
	Summary EvalSummary `json:"summary,omitempty,omitzero"`
}

// EvalScores Scores organized by category
type EvalScores struct {
	// Generation Generation quality scores (faithfulness, relevance, etc.)
	Generation map[string]EvaluatorScore `json:"generation,omitempty,omitzero"`

	// Retrieval Retrieval metric scores (recall, precision, ndcg, etc.)
	Retrieval map[string]EvaluatorScore `json:"retrieval,omitempty,omitzero"`
}

// EvalSummary Aggregate statistics across all evaluators
type EvalSummary struct {
	// AverageScore Average score across all evaluators
	AverageScore float32 `json:"average_score,omitempty,omitzero"`

	// Failed Number of evaluators that failed
	Failed int `json:"failed,omitempty,omitzero"`

	// Passed Number of evaluators that passed
	Passed int `json:"passed,omitempty,omitzero"`

	// Total Total number of evaluators run
	Total int `json:"total,omitempty,omitzero"`
}

// EvaluatorName Available evaluator types:
//
// **Retrieval metrics** (require ground_truth.relevant_ids):
// - recall: Recall@k - fraction of relevant docs retrieved
// - precision: Precision@k - fraction of retrieved docs that are relevant
// - ndcg: Normalized Discounted Cumulative Gain
// - mrr: Mean Reciprocal Rank
// - map: Mean Average Precision
//
// **LLM-as-judge metrics** (require judge config):
// - relevance: Is output relevant to query? (works on retrieval-only too)
// - faithfulness: Is output grounded in context?
// - completeness: Does output fully address query?
// - coherence: Is output well-structured?
// - safety: Is output safe/appropriate?
// - helpfulness: Is output useful?
// - correctness: Is output factually correct? (uses expectations)
// - citation_quality: Are citations accurate?
type EvaluatorName string

// EvaluatorScore Result from a single evaluator
type EvaluatorScore struct {
	// Metadata Additional evaluator-specific data
	Metadata map[string]interface{} `json:"metadata,omitempty,omitzero"`

	// Pass Whether the evaluation passed the threshold
	Pass bool `json:"pass,omitempty,omitzero"`

	// Reason Human-readable explanation of the result
	Reason string `json:"reason,omitempty,omitzero"`

	// Score Numeric score (0-1)
	Score float32 `json:"score,omitempty,omitzero"`
}

// ExaSearchConfig Configuration for Exa neural/semantic web search.
//
// Exa is optimized for semantic web search, highlights, and retrieved page
// contents for RAG and agent workflows.
//
// **Setup:**
// 1. Sign up at https://exa.ai
// 2. Get API key from dashboard
//
// **Docs:** https://docs.exa.ai
type ExaSearchConfig struct {
	// ApiKey Exa API key (or set EXA_API_KEY env var)
	ApiKey string `json:"api_key,omitempty,omitzero"`

	// CredentialsPath Service account JSON path for provider vertex. Shared Vertex credential field; see vertex.yaml#/components/schemas/VertexCredentials. Falls back to GOOGLE_APPLICATION_CREDENTIALS or ADC.
	CredentialsPath string `json:"credentials_path,omitempty,omitzero"`

	// DataStore Agent Search data store ID for provider vertex.
	DataStore string `json:"data_store,omitempty,omitzero"`

	// EndPublishedDate ISO date/time upper bound for published date filtering
	EndPublishedDate string `json:"end_published_date,omitempty,omitzero"`

	// Endpoint Provider endpoint override when applicable
	Endpoint string `json:"endpoint,omitempty,omitzero"`

	// ExcludeDomains Exclude results from these domains
	ExcludeDomains []string `json:"exclude_domains,omitempty,omitzero"`

	// IncludeContent Ask the provider to return extracted page content when supported
	IncludeContent bool `json:"include_content,omitempty,omitzero"`

	// IncludeDomains Only include results from these domains
	IncludeDomains []string `json:"include_domains,omitempty,omitzero"`

	// IncludeHighlights Ask the provider to return highlighted passages when supported
	IncludeHighlights bool `json:"include_highlights,omitempty,omitzero"`

	// Language Preferred language for results (e.g., 'en', 'es', 'fr')
	//
	// Example: en
	Language string `json:"language,omitempty,omitzero"`

	// Location Google Cloud location for provider vertex. Shared Vertex credential field; see vertex.yaml#/components/schemas/VertexCredentials. Falls back to GOOGLE_CLOUD_LOCATION, then global.
	Location string `json:"location,omitempty,omitzero"`

	// MaxResults Maximum number of search results to return
	MaxResults int `json:"max_results,omitempty,omitzero"`

	// NumResults Provider-specific result count override
	NumResults int `json:"num_results,omitempty,omitzero"`

	// ProjectId Google Cloud project ID for provider vertex. Shared Vertex credential field; see vertex.yaml#/components/schemas/VertexCredentials. Falls back to GOOGLE_CLOUD_PROJECT.
	ProjectId string `json:"project_id,omitempty,omitzero"`

	// Provider The web search provider to use.
	//
	// - **exa**: Exa neural/semantic web search API
	// - **serper**: Serper.dev Google Search API (simpler setup)
	// - **tavily**: Tavily AI Search API (optimized for RAG)
	// - **brave**: Brave Search API
	// - **you**: You.com Search API for agent and research workflows
	// - **linkup**: Linkup Search API for web search and content retrieval
	// - **vertex**: Google Cloud Agent Search / Vertex AI Search
	Provider WebSearchProvider `json:"provider"`

	// Region Preferred region for results (e.g., 'us', 'uk', 'de')
	//
	// Example: us
	Region string `json:"region,omitempty,omitzero"`

	// SafeSearch Enable safe search filtering
	SafeSearch *bool `json:"safe_search,omitempty"`

	// SearchType Search mode to request from Exa
	SearchType ExaSearchConfigSearchType `json:"search_type,omitempty,omitzero"`

	// ServingConfig Agent Search serving config ID for provider vertex. Defaults to default_config.
	ServingConfig string `json:"serving_config,omitempty,omitzero"`

	// StartPublishedDate ISO date/time lower bound for published date filtering
	StartPublishedDate string `json:"start_published_date,omitempty,omitzero"`

	// TimeoutMs Request timeout in milliseconds
	TimeoutMs int `json:"timeout_ms,omitempty,omitzero"`
}

// ExaSearchConfigSearchType Search mode to request from Exa
type ExaSearchConfigSearchType string

// ExactSortError defines model for ExactSortError.
type ExactSortError struct {
	// BudgetRejectionReason Stable budget rejection reason when the rejection was
	// budget-driven. Known values include
	// `text_exact_late_visibility_totals`,
	// `text_field_sort_candidate_window`,
	// `match_all_candidate_collect_limit`,
	// `match_all_exact_candidate_window`,
	// `sorted_segment_scan_window`, and
	// `distributed_merge_shard_window`.
	//
	//
	// Example: text_field_sort_candidate_window
	BudgetRejectionReason string `json:"budget_rejection_reason,omitempty,omitzero"`

	// Error Stable error class.
	//
	// Example: unsupported_exact_sort
	Error ExactSortErrorError `json:"error"`

	// Message Human-readable error summary.
	//
	// Example: exact sort is unsupported for this query
	Message string `json:"message"`

	// Reason Stable machine-readable rejection reason. Known exact-sort
	// reasons include `unmapped_field`, `non_sortable_field`,
	// `unsupported_sort_field`, `mixed_field_type`,
	// `field_not_sort_ready`, `filter_not_queryable`,
	// `invalid_cursor_arity`, `invalid_cursor_type`,
	// `invalid_sort_tuple`, `approximate_candidate_source`,
	// `candidate_budget_exceeded`, `missing_null_policy`,
	// `non_score_bearing_source`, `invalid_score_value`,
	// `count_only_ordered_page`, `stored_json_sort_disabled`,
	// `unsupported_exact_sort`, and `distributed_merge_unsupported`.
	//
	//
	// Example: field_not_sort_ready
	Reason string `json:"reason"`

	// SortRejectionDetail Stable user-facing exact-sort rejection detail. Internal storage
	// and planner details are reserved for logs, traces, and explicit
	// debug surfaces.
	//
	//
	// Example: field_not_sort_ready
	SortRejectionDetail string `json:"sort_rejection_detail"`

	// SortRejectionField Sort field associated with the rejection when safe to expose.
	//
	// Example: created_at
	SortRejectionField string `json:"sort_rejection_field"`

	// SortRejectionReason Stable exact-sort rejection reason; uses the same stable reason taxonomy as `reason`.
	//
	// Example: field_not_sort_ready
	SortRejectionReason string `json:"sort_rejection_reason"`

	// Status Example: 422
	Status ExactSortErrorStatus `json:"status"`
}

// ExactSortErrorError Stable error class.
